import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count outcomes
    cc = cd = dc = dd = 0
    for (me, opp) in history:
        if me == 'C':
            if opp == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if opp == 'C':
                dc += 1
            else:
                dd += 1

    # Last opponent action
    last_opp = history[-1][1]
    last_me = history[-1][0]

    # Early probing phase: alternate D/C initially to test
    if n <= 2:
        return 'D' if n == 1 else 'C'

    # Detect likely always-defect opponent: many DC occurrences early and no CC
    if n >= 5 and dc >= n - 2 and cc == 0:
        return 'D'

    # Detect likely always-cooperate: many CC and few DD
    if n >= 5 and cc >= n - 2:
        return 'C'

    # Tit-for-tat with occasional forgiveness and mild retaliation
    if last_opp == 'D':
        # Retaliate, but sometimes forgive to break death spirals
        if dd >= 3 and rng.random() < 0.15:
            return 'C'
        return 'D'
    else:
        # Cooperate, but occasionally probe if we've been exploited
        if dc > cc and rng.random() < 0.1:
            return 'D'
        return 'C'

